def _field_default(field: Any) -> Any:
    """Materialize a field's declared default for assignment to a state instance.

    Args:
        field: The field whose default to resolve.

    Returns:
        The factory-called default, or a deep copy of the static default.
    """
    if field.default_factory is not None:
        return field.default_factory()
    return copy.deepcopy(field.default)
